+        if (upperExclusive.onOrBefore(lowerInclusive)) throw new IllegalArgumentException();
+        return onOrAfter(lowerInclusive) && before(upperExclusive);
+    }
+
+    @Override
+    default int compareTo(T o) {
+        return Integer.compare(id(), o.id());
+    }
